<script setup>
import {ref} from 'vue'
import {useAuth} from '../stores/auth'
import {useCooldown,exclusive} from '../composables/cooldown'
import {sys,query,errorText} from '../api/client'
import Modal from '../components/Modal.vue'
const auth=useAuth(),cool=useCooldown('reset'),project=ref('TICKET'),confirm=ref(false),busy=ref(false),error=ref(''),success=ref('')
async function reset(){if(busy.value)return;busy.value=true;error.value='';success.value='';try{await exclusive(cool.key,async()=>{cool.refresh();if(cool.seconds.value)throw new Error('重置冷却尚未结束，请稍候。');await sys('post',`/api/sys-workspace/one/${encodeURIComponent(auth.user?.userId)}/reset`,null,{project:project.value});cool.start(300000);const event={project:project.value,at:Date.now()};localStorage.setItem(`practice:${auth.user?.userId}:reset-event`,JSON.stringify(event));window.dispatchEvent(new CustomEvent('practice-reset',{detail:event}));confirm.value=false;success.value='重置成功。访问码保持不变，请使用重新查询到的数据。';const projects=project.value==='ALL'?['ticket','repair']:[project.value.toLowerCase()];const r=await Promise.allSettled(projects.map(p=>query(p,p==='ticket'?'/activities':'/devices')));if(r.some(x=>x.status==='rejected'))success.value+=' 当前数据刷新失败，请到“我的项目数据”重新查询。';else success.value+=' 项目数据已重新获取。'})}catch(e){error.value=errorText(e)}finally{busy.value=false}}
</script>
<template><h1>重置我的实训数据</h1><p>当你需要重新练习时，可以将项目恢复为初始数据。</p><section class="panel reset-panel"><h2>选择重置范围</h2><div class="reset-options"><label v-for="[v,n,d] in [['TICKET','校园抢票','模拟用户、活动与票券'],['REPAIR','校园报修','模拟用户、设备、工单与图片'],['ALL','全部项目','同时恢复两个项目的数据']]" :key="v"><input v-model="project" type="radio" :value="v" :disabled="busy"><span><strong>{{n}}</strong><small>{{d}}</small></span></label></div><p class="alert warning">重置后，本项目中的操作数据将恢复为初始数据，请确认已保存需要保留的内容。</p><p>每次重置成功后，请间隔五分钟再进行下一次重置。两个项目共用等待时间。</p><div v-if="error" class="alert error" role="alert">{{error}}</div><div v-if="success" class="alert success" role="status">{{success}}</div><button :disabled="busy||cool.seconds.value>0" @click="confirm=true">{{busy?'正在重置…':cool.seconds.value?`请在${cool.label.value}后再次重置`:'重置所选项目'}}</button><p class="hint">重置后，请重新查询数据，不要继续使用原来的活动或工单ID。</p></section><Modal v-if="confirm" title="确认重置本人数据" @close="!busy&&(confirm=false)"><p>学号：{{auth.user?.userId}} · 范围：{{project==='ALL'?'全部项目':project==='TICKET'?'校园抢票':'校园报修'}}</p><p class="confirm-copy">重置后，本项目中的操作数据将恢复为初始数据，请确认已保存需要保留的内容。</p><div v-if="error" class="alert error" role="alert">{{error}}</div><button :disabled="busy||cool.seconds.value>0" @click="reset">{{busy?'正在重置…':'确认重置'}}</button></Modal></template>
